import React, { useState } from "react";
import { useNavigate } from "react-router-dom";

function RoleSelection() {
  const [selectedRole, setSelectedRole] = useState(null);
  const navigate = useNavigate();

  const handleContinue = () => {
    if (selectedRole === "student") {
      navigate("/dashboard");
    } else {
      alert("Only Student Dashboard is implemented for now!");
    }
  };

  return (
    <div className="flex flex-col items-center justify-center min-h-screen bg-purple-100">
      <h2 className="text-2xl font-bold mb-6">Select Your Role</h2>
      <div className="flex gap-6">
        <button
          className={`px-6 py-2 rounded-lg shadow ${
            selectedRole === "student"
              ? "bg-purple-600 text-white"
              : "bg-white border"
          }`}
          onClick={() => setSelectedRole("student")}
        >
          Student
        </button>
        <button
          className={`px-6 py-2 rounded-lg shadow ${
            selectedRole === "teacher"
              ? "bg-purple-600 text-white"
              : "bg-white border"
          }`}
          onClick={() => setSelectedRole("teacher")}
        >
          Teacher
        </button>
      </div>
      <button
        className="mt-6 px-6 py-2 bg-purple-600 text-white rounded-lg shadow"
        onClick={handleContinue}
      >
        Continue
      </button>
    </div>
  );
}

export default RoleSelection;
